<?php
require __DIR__ . '/includes/bootstrap.php';
$current=require_login();
$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    verify_csrf(); $action=$_POST['action']??'';
    if($current['role']==='owner' && $action==='review_seller'){
        $applicationId=(int)($_POST['application_id']??0); $decision=$_POST['decision']??'';
        if(!in_array($decision,['approved','rejected'],true)){flash('Pilihan peninjauan tidak valid.','error');redirect('dashboard.php#pendaftaran-penjual');}
        $reviewStmt=$pdo->prepare('SELECT user_id,application_status FROM seller_applications WHERE id=?');$reviewStmt->execute([$applicationId]);$application=$reviewStmt->fetch();
        if(!$application || $application['application_status']!=='pending'){flash('Permohonan sudah ditinjau atau tidak ditemukan.','error');redirect('dashboard.php#pendaftaran-penjual');}
        $pdo->beginTransaction();
        $pdo->prepare('UPDATE seller_applications SET application_status=?,reviewed_at=NOW() WHERE id=? AND application_status=\'pending\'')->execute([$decision,$applicationId]);
        $pdo->prepare('UPDATE users SET is_active=? WHERE id=? AND role=\'seller\'')->execute([$decision==='approved'?1:0,(int)$application['user_id']]);
        $pdo->prepare('UPDATE seller_business_profiles SET application_status=?,reviewed_by=?,reviewed_at=NOW() WHERE user_id=?')->execute([$decision,(int)$current['id'],(int)$application['user_id']]);
        $pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,reason,after_data,ip_address) VALUES(?,?,?,?,?,?,?)')->execute([(int)$current['id'],'seller_application_'.$decision,'seller_application',$applicationId,'Owner meninjau pendaftaran penjual',json_encode(['decision'=>$decision]),$_SERVER['REMOTE_ADDR']??null]);
        $pdo->commit(); flash($decision==='approved'?'Permohonan disetujui. Penjual sekarang dapat login.':'Permohonan ditolak.'); redirect('dashboard.php#pendaftaran-penjual');
    }
    if($current['role']==='seller' && $action==='seller_update_suborder'){
        $subId=(int)($_POST['seller_order_id']??0);$next=$_POST['next_status']??'';$carrier=trim($_POST['carrier']??'');$tracking=trim($_POST['tracking_number']??'');
        $map=['new'=>['confirmed','cancelled'],'confirmed'=>['packing','cancelled'],'packing'=>['ready_to_ship'],'ready_to_ship'=>['shipping'],'shipping'=>['delivered'],'delivered'=>[],'awaiting_cod'=>['packing'],'issue'=>[],'completed'=>[],'cancelled'=>[]];
        $pdo->beginTransaction();
        try{$q=$pdo->prepare('SELECT so.*,o.customer_id,o.id parent_order FROM seller_orders so JOIN orders o ON o.id=so.order_id WHERE so.id=? AND so.seller_id=? FOR UPDATE');$q->execute([$subId,(int)$current['id']]);$sub=$q->fetch();if(!$sub)throw new RuntimeException('Pesanan ini tidak terhubung dengan tokomu.');if(!in_array($next,$map[$sub['status']]??[],true))throw new RuntimeException('Perubahan status tersebut tidak diizinkan.');if($next==='shipping'&&($carrier===''||$tracking===''))throw new RuntimeException('Isi nama kurir dan nomor resi sebelum menandai pesanan dikirim.');
        if($next==='cancelled'){$restock=$pdo->prepare('UPDATE products p JOIN order_items i ON i.product_id=p.id SET p.stock=p.stock+i.quantity WHERE i.order_id=? AND i.seller_id=?');$restock->execute([(int)$sub['order_id'],(int)$current['id']]);}
        $upd=$pdo->prepare("UPDATE seller_orders SET status=?,carrier=IF(?='',carrier,?),tracking_number=IF(?='',tracking_number,?),seller_note=? WHERE id=? AND seller_id=?");$upd->execute([$next,$carrier,$carrier,$tracking,$tracking===''?null:'Resi '.$tracking,$subId,(int)$current['id']]);
        $hist=$pdo->prepare('INSERT INTO order_status_history(seller_order_id,changed_by,from_status,to_status,reason) VALUES(?,?,?,?,?)');$hist->execute([$subId,(int)$current['id'],$sub['status'],$next,$next==='cancelled'?'Dibatalkan penjual sebelum pengiriman':($tracking!==''?'Kurir '.$carrier.' · resi '.$tracking:null)]);
        $buyerText='Subpesanan #'.$subId.' berubah menjadi '.str_replace('_',' ',$next).'.';$notice=$pdo->prepare("INSERT INTO notifications(recipient_id,kind,title,body,target_url,reference_type,reference_id,dedupe_key) VALUES(?,'order_status','Perbarui pesanan',?,'dashboard.php','seller_order',?,?)");$notice->execute([(int)$sub['customer_id'],$buyerText,$subId,'suborder:'.$subId.':status:'.$next]);
        $pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,after_data,ip_address) VALUES(?,?,?,?,?,?)')->execute([(int)$current['id'],'seller_order_status_changed','seller_order',$subId,json_encode(['from'=>$sub['status'],'to'=>$next]),$_SERVER['REMOTE_ADDR']??null]);
        $all=$pdo->prepare("SELECT COUNT(*) total,SUM(status='cancelled') cancelled,SUM(status='completed') completed,SUM(status IN ('shipping','delivered')) in_transit,SUM(status IN ('confirmed','packing','ready_to_ship','awaiting_cod')) processing FROM seller_orders WHERE order_id=?");$all->execute([(int)$sub['order_id']]);$agg=$all->fetch();$parentStatus=(int)$agg['cancelled']===(int)$agg['total']?'dibatalkan':((int)$agg['completed']===(int)$agg['total']?'selesai':((int)$agg['in_transit']>0?'dikirim':((int)$agg['processing']>0?'diproses':'baru')));$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$parentStatus,(int)$sub['order_id']]);$pdo->commit();flash('Status subpesanan berhasil diperbarui.');
        }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Status belum tersimpan. Periksa migration database.','error');}redirect('dashboard.php#pesanan');
    }
    if($current['role']==='seller' && $action==='mark_cod_received'){
        $subId=(int)($_POST['seller_order_id']??0);$q=$pdo->prepare("SELECT id,order_id FROM seller_orders WHERE id=? AND seller_id=? AND status='delivered' AND payment_method='cod' AND payment_status='unpaid'");$q->execute([$subId,(int)$current['id']]);$sub=$q->fetch();if(!$sub){flash('COD baru dapat dikonfirmasi setelah pesanan berstatus terkirim.','error');redirect('dashboard.php#pesanan');}
        $pdo->beginTransaction();$pdo->prepare("UPDATE seller_orders SET payment_status='received' WHERE id=? AND seller_id=?")->execute([$subId,(int)$current['id']]);$pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,reason,ip_address) VALUES(?,?,?,?,?,?)')->execute([(int)$current['id'],'cod_payment_received','seller_order',$subId,'Penjual mengonfirmasi penerimaan COD',$_SERVER['REMOTE_ADDR']??null]);$pdo->commit();flash('Pembayaran COD dicatat diterima. Pembeli dapat mengonfirmasi pesanan selesai.');redirect('dashboard.php#pesanan');
    }
    if($current['role']==='customer' && $action==='buyer_confirm_received'){
    if($current['role']==='customer' && $action==='buyer_confirm_received'){
        $subId=(int)($_POST['seller_order_id']??0); $pdo->beginTransaction();
        $q=$pdo->prepare("SELECT so.* FROM seller_orders so JOIN orders o ON o.id=so.order_id WHERE so.id=? AND o.customer_id=? FOR UPDATE"); $q->execute([$subId,(int)$current['id']]); $sub=$q->fetch();
        if(!$sub || $sub['status']!=='delivered' || $sub['payment_status']!=='received'){ $pdo->rollBack(); flash('Pesanan belum memenuhi syarat selesai.','error'); redirect('dashboard.php#pesanan'); }
        $pdo->prepare("UPDATE seller_orders SET status='completed' WHERE id=?")->execute([$subId]);
        $pdo->prepare('INSERT INTO order_status_history(seller_order_id,changed_by,from_status,to_status,reason) VALUES(?,?,?,?,?)')->execute([$subId,(int)$current['id'],'delivered','completed','Pembeli mengonfirmasi barang diterima dan COD lunas']);
        $pdo->prepare("INSERT INTO notifications(recipient_id,kind,title,body,target_url,reference_type,reference_id,dedupe_key) VALUES(?,'order_status','Pesanan selesai',?,'dashboard.php','seller_order',?,?)")->execute([(int)$sub['seller_id'],'Pembeli mengonfirmasi subpesanan #'.$subId.' selesai.',$subId,'suborder:'.$subId.':completed']);
        $pdo->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,ip_address) VALUES(?,?,?,?,?)')->execute([(int)$current['id'],'buyer_confirmed_delivery','seller_order',$subId,$_SERVER['REMOTE_ADDR']??null]);
        $remaining=$pdo->prepare("SELECT COUNT(*) FROM seller_orders WHERE order_id=? AND status NOT IN ('completed','cancelled')"); $remaining->execute([(int)$sub['order_id']]); if((int)$remaining->fetchColumn()===0)$pdo->prepare("UPDATE orders SET status='selesai' WHERE id=?")->execute([(int)$sub['order_id']]);
        $pdo->commit(); flash('Pesanan ditandai selesai.'); redirect('dashboard.php#pesanan');
    }
    }
    http_response_code(403);exit('Aksi tidak diizinkan.');
}
layout_start('Dashboard');show_flash();
?>
