$summary=$pdo->query("SELECT COUNT(*) order_count, COALESCE(SUM(CASE WHEN status<>'dibatalkan' THEN total ELSE 0 END),0) revenue, SUM(status='baru') new_orders FROM orders")->fetch();
$customers=(int)$pdo->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn();$sellers=$pdo->query("SELECT id,name,email,created_at FROM users WHERE role='seller' ORDER BY id DESC")->fetchAll();$allProducts=$pdo->query('SELECT p.*,u.name seller_name FROM products p LEFT JOIN users u ON u.id=p.seller_id ORDER BY p.id DESC')->fetchAll();$allOrders=$pdo->query("SELECT o.*,u.email,(SELECT GROUP_CONCAT(CONCAT(i.product_name,' ×',i.quantity) SEPARATOR ', ') FROM order_items i WHERE i.order_id=o.id) items FROM orders o JOIN users u ON u.id=o.customer_id ORDER BY o.created_at DESC")->fetchAll();$users=$pdo->query("SELECT id,name,email,phone,role,is_active,created_at FROM users ORDER BY role,id DESC")->fetchAll();$sellerApplications=$pdo->query("SELECT a.*,u.name seller_name,u.email seller_email,u.phone seller_phone FROM seller_applications a JOIN users u ON u.id=a.user_id WHERE a.application_status='pending' ORDER BY a.created_at ASC")->fetchAll();$totalAccounts=count($users);$onlineUsers=0;try{$onlineUsers=(int)$pdo->query("SELECT COUNT(*) FROM user_activity WHERE last_seen_at>=NOW()-INTERVAL 5 MINUTE")->fetchColumn();}catch(PDOException $exception){}
$chartRows=$pdo->query("SELECT DATE(created_at) day, SUM(CASE WHEN status<>'dibatalkan' THEN total ELSE 0 END) amount FROM orders WHERE created_at >= CURRENT_DATE - INTERVAL 6 DAY GROUP BY DATE(created_at) ORDER BY day")->fetchAll();$chart=[];for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime("-$i days"));$chart[$day]=0;}foreach($chartRows as $row){if(isset($chart[$row['day']]))$chart[$row['day']]=(int)$row['amount'];}
$registrationRows=$pdo->query("SELECT DATE(created_at) day,COUNT(*) total FROM users WHERE created_at>=CURRENT_DATE-INTERVAL 6 DAY GROUP BY DATE(created_at) ORDER BY day")->fetchAll();$registrationChart=[];for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime("-$i days"));$registrationChart[$day]=0;}foreach($registrationRows as $row){if(isset($registrationChart[$row['day']]))$registrationChart[$row['day']]=(int)$row['total'];}
$orderRows=$pdo->query("SELECT DATE(created_at) day,COUNT(*) total FROM orders WHERE created_at>=CURRENT_DATE-INTERVAL 6 DAY GROUP BY DATE(created_at) ORDER BY day")->fetchAll();$orderChart=[];for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime("-$i days"));$orderChart[$day]=0;}foreach($orderRows as $row){if(isset($orderChart[$row['day']]))$orderChart[$row['day']]=(int)$row['total'];}
