$productsStmt=$pdo->prepare('SELECT p.id,p.name,p.category,p.price,p.stock,COALESCE(SUM(CASE WHEN o.status<>\'dibatalkan\' THEN oi.quantity ELSE 0 END),0) sold,COALESCE(SUM(CASE WHEN o.status<>\'dibatalkan\' THEN oi.line_total ELSE 0 END),0) revenue FROM products p LEFT JOIN order_items oi ON oi.product_id=p.id AND oi.seller_id=? LEFT JOIN orders o ON o.id=oi.order_id WHERE p.seller_id=? GROUP BY p.id ORDER BY p.name');$productsStmt->execute([$current['id'],$current['id']]);$sellerProducts=$productsStmt->fetchAll();
$ordersStmt=$pdo->prepare("SELECT so.id seller_order_id,so.status seller_status,so.payment_method,so.payment_status,so.carrier,so.tracking_number,o.id,o.customer_name,o.phone,o.address,o.created_at,SUM(oi.quantity) quantity,SUM(oi.line_total) subtotal,GROUP_CONCAT(CONCAT(oi.product_name,' ×',oi.quantity) SEPARATOR ', ') items FROM seller_orders so JOIN orders o ON o.id=so.order_id JOIN order_items oi ON oi.order_id=o.id AND oi.seller_id=so.seller_id WHERE so.seller_id=? GROUP BY so.id ORDER BY o.created_at DESC");$ordersStmt->execute([$current['id']]);$sellerOrders=$ordersStmt->fetchAll();$sellerRevenue=array_sum(array_map(fn($row)=>(int)$row['revenue'],$sellerProducts));$sellerUnits=array_sum(array_map(fn($row)=>(int)$row['sold'],$sellerProducts));
$sellerSalesRowsStmt=$pdo->prepare("SELECT DATE(o.created_at) day,SUM(oi.line_total) amount FROM orders o JOIN order_items oi ON oi.order_id=o.id WHERE oi.seller_id=? AND o.status<>'dibatalkan' AND o.created_at>=CURRENT_DATE-INTERVAL 6 DAY GROUP BY DATE(o.created_at) ORDER BY day");$sellerSalesRowsStmt->execute([$current['id']]);$sellerSalesRows=$sellerSalesRowsStmt->fetchAll();$sellerSalesChart=[];for($i=6;$i>=0;$i--){$day=date('Y-m-d',strtotime("-$i days"));$sellerSalesChart[$day]=0;}foreach($sellerSalesRows as $row){if(isset($sellerSalesChart[$row['day']]))$sellerSalesChart[$row['day']]=(int)$row['amount'];}
