<?php else:
$stmt=$pdo->prepare("SELECT o.*,(SELECT GROUP_CONCAT(CONCAT(i.product_name,' ×',i.quantity) SEPARATOR ', ') FROM order_items i WHERE i.order_id=o.id) items FROM orders o WHERE o.customer_id=? ORDER BY o.created_at DESC");$stmt->execute([$current['id']]);$myOrders=$stmt->fetchAll();
?>
<section class="panel"><div class="panel-heading"><div><span class="eyebrow">AKUN PELANGGAN</span><h2>Pesanan saya</h2><p>Pantau status belanjaanmu di sini.</p></div><a href="shop.php#produk" class="button button-dark">Belanja lagi →</a></div><div class="table-wrap"><table><thead><tr><th>No. pesanan</th><th>Produk</th><th>Total</th><th>Status</th><th>Tanggal</th></tr></thead><tbody><?php foreach($myOrders as $order): ?><tr><td>#<?=(int)$order['id']?></td><td><?=h($order['items']??'—')?></td><td><?=rupiah((int)$order['total'])?></td><td><span class="status-pill"><?=h(ucfirst($order['status']))?></span></td><td><?=h($order['created_at'])?></td></tr><?php endforeach; if(!$myOrders): ?><tr><td colspan="5">Kamu belum memiliki pesanan. <a href="shop.php#produk">Lihat produk</a></td></tr><?php endif; ?></tbody></table></div></section>
